  it.todo("dsolve_system(eqs)");
  // a result object that did not come from the library
  //   dsolve_system(eqs, ics={f(0): 1, g(0): 0})
  //   => [[Eq(f(x), exp(x)/2 + exp(-x)/2), Eq(g(x), exp(x)/2 - exp(-x)/2)]]
