describe("doctests of sympy.solvers.ode.subscheck", () => {
  // a primitive result that no library call returned
  //   checkodesol(f(x).diff(x), Eq(f(x), C1))
  //   => (True, 0)
  it.todo("checkodesol(f(x).diff(x), Eq(f(x), C1))");
  it("checkodesol(f(x).diff(x, 2), x**2)", () => {
    const x = new Sym('x');
    expect(sympyMatches([isUnsolved(at(checkodesol(derivative((SymFunction('f'))(x), [[x, 2]]), pow(x, 2)), 1)), at(checkodesol(derivative((SymFunction('f'))(x), [[x, 2]]), pow(x, 2)), 1)], '(False, 2)')).toBe(true);
  });
  // a primitive result that no library call returned
  //   checkodesol(eqs, sol)
  //   => (True, [0, 0])
  it.todo("checkodesol(eqs, sol)");
  // a primitive result that no library call returned
  //   checksysodesol(eq, sol)
  //   => (True, [0, 0])
  it.todo("checksysodesol(eq, sol)");
  // the arguments do not type-check against the public API
  //   checksysodesol(eq, sol)
  //   => (True, [0, 0])
  it.todo("checksysodesol(eq, sol) (2)");
  it("sub_func_doit(3*Derivative(y(x), x) - 1, y(x), x)", () => {
    const x = new Sym('x');
    expect(sympyStr(subFuncDoit(add(-1, mul(3, derivative((SymFunction('y'))(x), [[x, 1]]))), (SymFunction('y'))(x), x))).toBe('2');
  });
  it("sub_func_doit(x*Derivative(y(x), x) - y(x)**2 + y(x), y(x),", () => {
    const [x, z] = symbols('x z');
    expect(sympyStr(subFuncDoit(add(mul(-1, pow((SymFunction('y'))(x), 2)), mul(x, derivative((SymFunction('y'))(x), [[x, 1]])), (SymFunction('y'))(x)), (SymFunction('y'))(x), mul(pow(x, -1), pow(add(z, pow(x, -1)), -1))))).toBe('x*(-1/(x**2*(z + 1/x)) + 1/(x**3*(z + 1/x)**2)) + 1/(x*(z + 1/x)) - 1/(x**2*(z + 1/x)**2)');
  });
});

